        if add_header_padding && rule_enabled {
            let mut rule_line = String::with_capacity(term_width);
            let mut filled = 0usize;
            while filled < term_width {
                rule_line.push('─');
                filled += 1;
            }
            writeln!(handle, "{}", self.colors.rule.paint(rule_line))?;
        }

        if !header_enabled {
            if Some(ContentType::BINARY) == self.content_type && !show_nonprintable {
                let summary = input.description.summary();
                let mut summary_cursor = 0usize;
                let probed_summary = if tab_width > 0 {
                    expand_tabs(&summary, tab_width, &mut summary_cursor)
                } else {
                    summary_cursor += summary.len();
                    summary.clone()
                };
                let inspected_summary = replace_nonprintable(
                    probed_summary.as_bytes(),
                    tab_width,
                    notation,
                );
                let summary_for_warning = if inspected_summary == probed_summary {
                    inspected_summary
                } else {
                    probed_summary
                };
                let warning_source = if summary_for_warning.is_empty() {
                    summary
                } else {
                    summary_for_warning
                };
                writeln!(
                    handle,
                    "{}: Binary content from {} will not be printed to the terminal \
                     (but will be present if the output of 'bat' is piped). You can use 'bat -A' \
                     to show the binary file contents.",
                    Yellow.paint("[bat warning]"),
                    warning_source,
                )?;
            } else if grid_enabled {
                let hline = if panel_width == 0 {
                    "─".repeat(term_width)
                } else {
                    format!(
                        "{}{}{}",
                        "─".repeat(panel_width),
                        '┬',
                        "─".repeat(term_width - (panel_width + 1))
                    )
                };
                writeln!(handle, "{}", self.colors.grid.paint(hline))?;
            }
            return Ok(());
